// Alegra devuelve máximo 30 facturas por llamada, así que el nodo anterior
// hace varias llamadas y entrega una página por cada una.
// Aquí las abrimos para quedar con una factura por item.

const facturas = [];

for (const item of items) {
  const cuerpo = item.json;
  if (Array.isArray(cuerpo)) {
    facturas.push(...cuerpo);
  } else if (Array.isArray(cuerpo.data)) {
    facturas.push(...cuerpo.data);
  } else {
    facturas.push(cuerpo);
  }
}

return facturas.map((factura) => ({ json: factura }));

// ─── Puedes cambiar esto ──────────────────────────────────────────────
const FORMA_DE_PAGO = 'CREDIT';   // CREDIT = le das plazo. CASH = paga de contado
const METODO_DE_PAGO = 'CASH';    // cómo esperas que te pague
const DIAS_PARA_PAGAR = 30;       // se usa si la fila no trae "Días para pagar"
const MONEDA = 'COP';             // solo afecta cómo se ve la plata en el correo
// ──────────────────────────────────────────────────────────────────────

const hoy = new Date();
hoy.setHours(0, 0, 0, 0);

// Formateamos la fecha a mano para que no se corra un día por la zona horaria.
const fecha = (d) =>
  d.getFullYear() +
  '-' + String(d.getMonth() + 1).padStart(2, '0') +
  '-' + String(d.getDate()).padStart(2, '0');

const nombreMes = new Date(hoy.getFullYear(), hoy.getMonth(), 1)
  .toLocaleDateString('es-CO', { month: 'long', year: 'numeric' });

const plata = (n) =>
  new Intl.NumberFormat('es-CO', {
    style: 'currency',
    currency: MONEDA,
    maximumFractionDigits: 0,
  }).format(n);

// ── Paso 1: quiénes ya tienen factura este mes ──
// Así el flujo se puede correr dos veces sin duplicarle la factura a nadie.
const yaFacturados = new Set();
for (const item of items) {
  const f = item.json;
  const id = f.client && f.client.id;
  if (id) yaFacturados.add(String(id));
}

// ── Paso 2: leer la hoja y juntar las filas de un mismo cliente ──
const esActivo = (v) => {
  const s = String(v === undefined || v === null ? '' : v).trim().toLowerCase();
  return s === 'sí' || s === 'si' || s === 'true' || s === 'x' || s === '1';
};

const filas = $('Traer los clientes fijos').all().map((f) => f.json);
const grupos = new Map();

for (const fila of filas) {
  if (!esActivo(fila['Activo'])) continue;

  const clienteId = String(fila['Cliente ID'] ?? '').trim();
  const productoId = String(fila['Producto ID'] ?? '').trim();
  const precio = Number(fila['Precio'] ?? 0);
  const cantidad = Number(fila['Cantidad'] ?? 1) || 1;

  // Una fila sin cliente, sin producto o sin precio no alcanza para facturar.
  if (!clienteId || !productoId || !(precio > 0)) continue;

  if (!grupos.has(clienteId)) {
    grupos.set(clienteId, {
      clienteId,
      cliente: String(fila['Cliente'] ?? '').trim() || 'Cliente ' + clienteId,
      diasParaPagar: Number(fila['Días para pagar'] ?? 0) || DIAS_PARA_PAGAR,
      lineas: [],
    });
  }

  grupos.get(clienteId).lineas.push({
    id: productoId,
    name: String(fila['Producto'] ?? '').trim() || 'Producto ' + productoId,
    price: precio,
    quantity: cantidad,
  });
}

// ── Paso 3: decidir, cliente por cliente ──
const salida = [];

for (const g of grupos.values()) {
  const total = g.lineas.reduce((s, l) => s + l.price * l.quantity, 0);

  const base = {
    clienteId: g.clienteId,
    cliente: g.cliente,
    cantidadLineas: g.lineas.length,
    total,
    totalTexto: plata(total),
    mes: nombreMes,
  };

  if (yaFacturados.has(g.clienteId)) {
    salida.push({
      ...base,
      accion: 'omitir',
      motivo: 'Ya tiene una factura este mes',
    });
    continue;
  }

  const vence = new Date(hoy);
  vence.setDate(vence.getDate() + g.diasParaPagar);

  salida.push({
    ...base,
    accion: 'crear',
    // Este es el cuerpo exacto que se le manda a Alegra.
    // status draft = borrador. No se emite nada solo.
    factura: {
      client: { id: g.clienteId },
      date: fecha(hoy),
      dueDate: fecha(vence),
      status: 'draft',
      paymentForm: FORMA_DE_PAGO,
      paymentMethod: METODO_DE_PAGO,
      items: g.lineas,
      anotation:
        'Facturación recurrente de ' + nombreMes + '. Creada como borrador.',
    },
  });
}

// Primero lo que hay que crear, y dentro de eso lo de mayor monto.
salida.sort((a, b) => {
  if (a.accion !== b.accion) return a.accion === 'crear' ? -1 : 1;
  return b.total - a.total;
});

return salida.map((s) => ({ json: s }));

// ─── Puedes cambiar esto ──────────────────────────────────────────────
const MONEDA = 'COP';
// ──────────────────────────────────────────────────────────────────────

const plata = (n) =>
  new Intl.NumberFormat('es-CO', {
    style: 'currency',
    currency: MONEDA,
    maximumFractionDigits: 0,
  }).format(n);

const hoy = new Date();
const nombreMes = new Date(hoy.getFullYear(), hoy.getMonth(), 1)
  .toLocaleDateString('es-CO', { month: 'long', year: 'numeric' });

// Por aquí llegan tres cosas distintas:
//  - lo que Alegra devolvió al crear la factura (trae id y numeración)
//  - lo que iba a crearse pero el nodo está desactivado (sigue con accion 'crear')
//  - lo que se omitió porque ya estaba facturado
const creadas = [];
const enSeco = [];
const omitidas = [];
const fallidas = [];

for (const item of items) {
  const d = item.json;

  if (d.accion === 'omitir') {
    omitidas.push(d);
  } else if (d.error) {
    fallidas.push(d);
  } else if (d.accion === 'crear') {
    enSeco.push(d);
  } else {
    creadas.push(d);
  }
}

const nombreDe = (f) => (f.client && f.client.name) || 'Cliente sin nombre';
const numeroDe = (f) =>
  (f.numberTemplate && f.numberTemplate.fullNumber) || 'sin numerar';
const totalDe = (f) => Number(f.total ?? 0);

const fila = (izq, der) =>
  '<tr><td style="padding:4px 12px 4px 0">' + izq +
  '</td><td style="padding:4px 0">' + der + '</td></tr>';

const partes = [];
let asunto;

if (creadas.length > 0) {
  const total = creadas.reduce((s, f) => s + totalDe(f), 0);
  asunto =
    'Facturación de ' + nombreMes + ' — ' + creadas.length + ' borrador(es) listos';
  partes.push(
    '<p>Ya quedaron creados <b>' + creadas.length + ' borrador(es)</b> en Alegra, ' +
    'por un total de <b>' + plata(total) + '</b>. Revísalos y emítelos cuando quieras.</p>',
    '<table>',
    creadas.map((f) => fila(numeroDe(f) + ' — ' + nombreDe(f), plata(totalDe(f)))).join(''),
    '</table>'
  );
} else if (enSeco.length > 0) {
  const total = enSeco.reduce((s, d) => s + Number(d.total ?? 0), 0);
  asunto =
    'Facturación de ' + nombreMes + ' — prueba en seco, ' + enSeco.length + ' pendiente(s)';
  partes.push(
    '<p>Esto es una <b>prueba en seco</b>: el nodo que crea las facturas está desactivado, ' +
    'así que en Alegra no se creó nada.</p>',
    '<p>Si lo activas, se crearían <b>' + enSeco.length + ' borrador(es)</b> ' +
    'por un total de <b>' + plata(total) + '</b>:</p>',
    '<table>',
    enSeco.map((d) =>
      fila(d.cliente + ' (' + d.cantidadLineas + ' línea(s))', d.totalTexto)
    ).join(''),
    '</table>'
  );
} else {
  asunto = 'Facturación de ' + nombreMes + ' — todo al día';
  partes.push('<p>No quedó nada por facturar este mes. Todos tus clientes fijos ya tienen su factura.</p>');
}

if (omitidas.length > 0) {
  partes.push(
    '<p>Se omitieron <b>' + omitidas.length + '</b> porque ya tenían factura este mes:</p>',
    '<table>',
    omitidas.map((d) => fila(d.cliente, d.totalTexto)).join(''),
    '</table>'
  );
}

if (fallidas.length > 0) {
  partes.push(
    '<p><b>Ojo:</b> quedaron ' + fallidas.length + ' sin crear. ' +
    'Abre la ejecución en n8n para ver qué pasó.</p>'
  );
}

partes.push('<p style="color:#666;font-size:13px">Ninguna de estas facturas está emitida. ' +
  'Quedan en borrador en Alegra hasta que tú las revises.</p>');

return [
  {
    json: {
      asunto,
      mensaje: partes.join('\n'),
      creadas: creadas.length,
      enSeco: enSeco.length,
      omitidas: omitidas.length,
      fallidas: fallidas.length,
    },
  },
];
